int Find(int[] a, int target) {
    int low = 0, high = a.Length;
    while (low < high) {
        int middle = low + (high - low) / 2;
        if (a[middle] == target) return middle;
        if (a[middle] < target) low = middle + 1; else high = middle;
    } return -1;
}

